// Entities: making them, the tree they are in, where they are, and their names, copies and appearance.

#include "scene_internal.hpp"

using namespace bb;
using namespace bb::scene;

namespace bb {
	float ambient_light[3] = { 0.5f, 0.5f, 0.5f };
}

namespace bb::scene {

	static buffer<entity*>  entities; // Handle - 1, null if freed.
	buffer<surface*> surface_table;
	float            tformed[3] = { 0, 0, 0 };

	float rad(float degrees) { return degrees * (pi / 180.0f); }
	float deg(float radians) { return radians * (180.0f / pi); }

	[[noreturn]] void fail(const char* what, int handle)
	{
		char buffer[128];
		snprintf(buffer, sizeof(buffer), "%s: entity or surface %d does not exist.", what, handle);
		bb_runtime_error(buffer);
		exit(1);
	}

	entity* need(int handle, const char* what)
	{
		entity* e = get_entity(handle);
		if (!e) {
			fail(what, handle);
		}
		return e;
	}

	entity* need_kind(int handle, int kind, const char* what)
	{
		entity* e = need(handle, what);
		if (e->kind != kind) {
			char buffer[128];
			snprintf(buffer, sizeof(buffer), "%s: entity %d is not the right kind of entity.", what, handle);
			bb_runtime_error(buffer);
			exit(1);
		}
		return e;
	}

	surface* need_surface(int handle, const char* what)
	{
		if ((handle < 1) || (uint32_t(handle) > surface_table.size) || !surface_table[uint32_t(handle) - 1]) {
			fail(what, handle);
		}
		return surface_table[uint32_t(handle) - 1];
	}

	int add_entity(int kind, int parent)
	{
		entity* e = new entity();
		e->kind   = kind;
		if (parent) {
			need(parent, "CreateEntity");
			e->parent = parent;
		}
		for (uint32_t i = 0; i < entities.size; i++) {
			if (!entities[i]) {
				entities[i] = e;
				return int(i) + 1;
			}
		}
		entities.push(e);
		return int(entities.size);
	}

	// An entity lets go of a surface: it is gone once the last entity that has it is.
	static void release_surface(surface* s)
	{
		if (--s->refs > 0) {
			return;
		}
		for (uint32_t i = 0; i < surface_table.size; i++) {
			if (surface_table[i] == s) {
				surface_table[i] = nullptr;
			}
		}
		bb_release_surface_gpu(s->gpu);
		if (s->skin) {
			destroy_skin(s->skin);
		}
		s->vertices.release();
		s->indices.release();
		delete s;
	}

	int surface_handle(surface* s)
	{
		for (uint32_t i = 0; i < surface_table.size; i++) {
			if (surface_table[i] == s) {
				return int(i) + 1;
			}
		}
		surface_table.push(s);
		return int(surface_table.size);
	}

	static void destroy_entity(int handle)
	{
		entity* e = get_entity(handle);
		if (!e) {
			return;
		}
		// Children go with their parent.
		for (uint32_t i = 0; i < entities.size; i++) {
			if (entities[i] && (entities[i]->parent == handle)) {
				destroy_entity(int(i) + 1);
			}
		}
		for (uint32_t i = 0; i < e->surfaces.size; i++) {
			release_surface(e->surfaces[i]);
		}
		e->surfaces.release();
		if (e->anim) {
			destroy_animation(e->anim);
		}
		if (e->terrain) {
			free(e->terrain->heights);
			delete e->terrain;
		}
		free(e->name);
		delete e;
		entities[uint32_t(handle) - 1] = nullptr;
	}
	float clamp255(float v)
	{
		return (v < 0 ? 0 : (v > 255 ? 255 : v)) / 255.0f;
	}

	static float entity_axis(int32_t handle, int axis, int32_t global, const char* what)
	{
		entity* e = need(handle, what);
		if (!global) {
			return e->position[axis];
		}
		float world[16];
		world_matrix(handle, world);
		return world[12 + axis];
	}

	static float entity_angle(int32_t handle, int axis, int32_t global, const char* what)
	{
		entity* e = need(handle, what);
		if (!global) {
			return e->rotation[axis];
		}
		float world[16], angles[3];
		world_matrix(handle, world);
		euler_from_matrix_impl(world, angles);
		return angles[axis];
	}

	static bool same_name(const char* a, const char* b)
	{
		for (; *a && *b; a++, b++) {
			char x = (*a >= 'A' && *a <= 'Z') ? char(*a + 32) : *a, y = (*b >= 'A' && *b <= 'Z') ? char(*b + 32) : *b;
			if (x != y) {
				return false;
			}
		}
		return !*a && !*b;
	}

	static buffer<int> copy_was, copy_now;

	static int copy_entity(int source, int parent)
	{
		entity* from = get_entity(source);
		int     handle = add_entity(from->kind, parent);
		entity* to     = get_entity(handle);
		copy_was.push(source);
		copy_now.push(handle);

		// Everything is copied over, except what owns memory.
		entity copy = *from;
		copy.parent = parent;
		copy.name   = nullptr;
		copy.anim   = nullptr;
		if (copy_was.size == 1) {
			copy.hidden = false; // The copy of a hidden model, which is how programs keep their templates, can be seen.
		}
		copy.terrain = nullptr;
		if (from->terrain) {
			copy.terrain          = new terrain_data(*from->terrain);
			size_t count          = size_t(from->terrain->size + 1) * size_t(from->terrain->size + 1);
			copy.terrain->heights = static_cast<float*>(malloc(count * sizeof(float)));
			memcpy(copy.terrain->heights, from->terrain->heights, count * sizeof(float));
		}
		copy.surfaces.data = nullptr;
		copy.surfaces.size = copy.surfaces.cap = 0;
		*to = copy;
		for (uint32_t i = 0; i < from->surfaces.size; i++) {
			surface* original = from->surfaces[i];
			if (original->skin) {
				// The vertices of a skinned mesh follow the bones of this copy, so they can not be shared.
				surface* own = create_surface(handle);
				own->vertices.reserve(original->vertices.size);
				memcpy(own->vertices.data, original->vertices.data, original->vertices.size * sizeof(vertex3d));
				own->vertices.size = original->vertices.size;
				own->indices.reserve(original->indices.size);
				memcpy(own->indices.data, original->indices.data, original->indices.size * sizeof(uint32_t));
				own->indices.size = original->indices.size;
				own->painted = original->painted;
				own->paint   = original->paint;
				own->skin    = clone_skin(*original->skin);
			} else {
				original->refs++; // Shares the geometry.
				to->surfaces.push(original);
			}
		}
		if (from->name) {
			size_t length = strlen(from->name);
			to->name      = static_cast<char*>(malloc(length + 1));
			memcpy(to->name, from->name, length + 1);
		}

		for (uint32_t i = 0; i < entities.size; i++) {
			if (entities[i] && (entities[i]->parent == source) && (int(i) + 1 != handle)) {
				copy_entity(int(i) + 1, handle);
			}
		}
		if (from->anim) {
			to->anim = clone_animation(*from->anim, copy_was, copy_now);
		}
		return handle;
	}
} // namespace bb::scene

////////////////////////////////////////////////////////////////////////////////
// Shared with the renderer
////////////////////////////////////////////////////////////////////////////////
int bb::create_entity(int kind, int parent)
{
	return add_entity(kind, parent);
}

int bb::entity_count()
{
	return int(entities.size);
}

bb::entity* bb::get_entity(int handle)
{
	if ((handle < 1) || (uint32_t(handle) > entities.size)) {
		return nullptr;
	}
	return entities[uint32_t(handle) - 1];
}

void bb::world_matrix(int handle, float* out)
{
	entity* e = get_entity(handle);
	if (!e) {
		mat_identity(out);
		return;
	}
	float local[16];
	local_matrix(*e, local);
	if (e->parent) {
		float parent[16];
		world_matrix(e->parent, parent);
		mat_multiply(out, parent, local);
	} else {
		memcpy(out, local, sizeof(local));
	}
}

void bb::for_each_visible(int kind, void (*visit)(int, entity&, void*), void* user)
{
	for (uint32_t i = 0; i < entities.size; i++) {
		entity* e = entities[i];
		if (!e || (e->kind != kind) || e->hidden) {
			continue;
		}
		// Hidden parents hide their children.
		bool visible = true;
		for (int p = e->parent; p && visible; p = get_entity(p) ? get_entity(p)->parent : 0) {
			visible = get_entity(p) && !get_entity(p)->hidden;
		}
		if (visible) {
			visit(int(i) + 1, *e, user);
		}
	}
}

void bb::reset_movement(int handle)
{
	entity* e = get_entity(handle);
	if (!e) {
		return;
	}
	float m[16];
	world_matrix(handle, m);
	memcpy(e->old_matrix, m, sizeof(m));
	e->old_pos[0] = m[12];
	e->old_pos[1] = m[13];
	e->old_pos[2] = m[14];
	e->old_valid  = true;
}

extern "C" {

void bb_ambient_light(float r, float g, float b)
{
	ambient_light[0] = clamp255(r);
	ambient_light[1] = clamp255(g);
	ambient_light[2] = clamp255(b);
}

// Entities
// For the sound system, which has no business knowing about entities.
int bb_entity_world_matrix(int32_t handle, float* matrix)
{
	if (!get_entity(handle)) {
		return 0;
	}
	world_matrix(handle, matrix);
	return 1;
}

int32_t bb_create_pivot(int32_t parent)
{
	return add_entity(PIVOT, parent);
}

int32_t bb_create_camera(int32_t parent)
{
	return add_entity(CAMERA, parent);
}

int32_t bb_create_light(int32_t type, int32_t parent)
{
	int     handle = add_entity(LIGHT, parent);
	entity* e      = get_entity(handle);
	e->light_type  = (type < 1 || type > 3) ? 1 : type;
	return handle;
}

void bb_free_entity(int32_t handle)
{
	need(handle, "FreeEntity");
	destroy_entity(handle);
}

void bb_entity_parent(int32_t handle, int32_t parent, int32_t global)
{
	entity* e = need(handle, "EntityParent");
	if (parent) {
		need(parent, "EntityParent");
		for (int p = parent; p; p = get_entity(p)->parent) {
			if (p == handle) {
				bb_runtime_error("EntityParent: an entity can't be the child of its own child.");
				exit(1);
			}
		}
	}
	float world[16];
	world_matrix(handle, world);
	e->parent = parent;
	if (global) {
		// Keep the position in the world.
		float p[3] = { world[12], world[13], world[14] };
		world_to_local_point(*e, p, e->position);
	}
}

void bb_position_entity(int32_t handle, float x, float y, float z, int32_t global)
{
	entity* e = need(handle, "PositionEntity");
	float   p[3] = { x, y, z };
	if (global) {
		world_to_local_point(*e, p, e->position);
	} else {
		memcpy(e->position, p, sizeof(p));
	}
}

void bb_translate_entity(int32_t handle, float x, float y, float z, int32_t global)
{
	entity* e = need(handle, "TranslateEntity");
	if (global) {
		float world[16];
		world_matrix(handle, world);
		float p[3] = { world[12] + x, world[13] + y, world[14] + z };
		world_to_local_point(*e, p, e->position);
	} else {
		e->position[0] += x;
		e->position[1] += y;
		e->position[2] += z;
	}
}

// Moves relative to where the entity is facing.
void bb_move_entity(int32_t handle, float x, float y, float z)
{
	entity* e = need(handle, "MoveEntity");
	float   r[9];
	rotation_matrix(r, e->rotation);
	for (int row = 0; row < 3; row++) {
		e->position[row] += r[0 + row] * x + r[3 + row] * y + r[6 + row] * z;
	}
}

void bb_rotate_entity(int32_t handle, float pitch, float yaw, float roll, int32_t global)
{
	entity* e = need(handle, "RotateEntity");
	if (global && e->parent) {
		// Rotation of the entity in the world: remove the parent's rotation.
		float pm[16], inv[16], local[16], r[9];
		parent_matrix(*e, pm);
		affine_inverse(pm, inv);
		float target[3] = { pitch, yaw, roll };
		rotation_matrix(r, target);
		float rot[16];
		mat_identity(rot);
		for (int c = 0; c < 3; c++) {
			for (int row = 0; row < 3; row++) {
				rot[c * 4 + row] = r[c * 3 + row];
			}
		}
		mat_multiply(local, inv, rot);
		euler_from_matrix_impl(local, e->rotation);
		return;
	}
	e->rotation[0] = pitch;
	e->rotation[1] = yaw;
	e->rotation[2] = roll;
}

void bb_turn_entity(int32_t handle, float pitch, float yaw, float roll, int32_t global)
{
	entity* e = need(handle, "TurnEntity");
	if (global) {
		float world[16];
		world_matrix(handle, world);
		float current[3];
		euler_from_matrix_impl(world, current);
		bb_rotate_entity(handle, current[0] + pitch, current[1] + yaw, current[2] + roll, 1);
		return;
	}
	e->rotation[0] += pitch;
	e->rotation[1] += yaw;
	e->rotation[2] += roll;
}

void bb_scale_entity(int32_t handle, float x, float y, float z, int32_t global)
{
	(void)global;
	entity* e = need(handle, "ScaleEntity");
	if (e->terrain) {
		e->terrain->dirty = true; // Its normals depend on the scale.
	}
	e->scale[0] = x;
	e->scale[1] = y;
	e->scale[2] = z;
}

float bb_entity_x(int32_t handle, int32_t global) { return entity_axis(handle, 0, global, "EntityX"); }
float bb_entity_y(int32_t handle, int32_t global) { return entity_axis(handle, 1, global, "EntityY"); }
float bb_entity_z(int32_t handle, int32_t global) { return entity_axis(handle, 2, global, "EntityZ"); }

float bb_entity_pitch(int32_t handle, int32_t global) { return entity_angle(handle, 0, global, "EntityPitch"); }
float bb_entity_yaw(int32_t handle, int32_t global) { return entity_angle(handle, 1, global, "EntityYaw"); }
float bb_entity_roll(int32_t handle, int32_t global) { return entity_angle(handle, 2, global, "EntityRoll"); }

void bb_hide_entity(int32_t handle) { need(handle, "HideEntity")->hidden = true; }


void bb_show_entity(int32_t handle)
{
	entity* e = need(handle, "ShowEntity");
	e->hidden = false;
	reset_movement(handle); // Like in the original, showing something also forgets where it was, so it does not collide on the way.
}

void bb_entity_color(int32_t handle, float r, float g, float b)
{
	entity* e  = need(handle, "EntityColor");
	e->color[0] = clamp255(r);
	e->color[1] = clamp255(g);
	e->color[2] = clamp255(b);
}

void bb_entity_alpha(int32_t handle, float alpha)
{
	need(handle, "EntityAlpha")->alpha = alpha < 0 ? 0 : (alpha > 1 ? 1 : alpha);
}

void bb_entity_fx(int32_t handle, int32_t fx)
{
	need(handle, "EntityFX")->fx = fx;
}

void bb_entity_texture(int32_t handle, int32_t texture, int32_t frame, int32_t index)
{
	(void)frame;
	entity* e = need(handle, "EntityTexture");
	if (index == 0) {
		e->texture = texture;
	} else if ((index > 0) && (index < 8)) {
		e->layers[index - 1] = texture;
	}
}

float bb_entity_distance(int32_t a, int32_t b)
{
	need(a, "EntityDistance");
	need(b, "EntityDistance");
	float ma[16], mb[16];
	world_matrix(a, ma);
	world_matrix(b, mb);
	float dx = ma[12] - mb[12], dy = ma[13] - mb[13], dz = ma[14] - mb[14];
	return sqrtf(dx * dx + dy * dy + dz * dz);
}

void bb_point_entity(int32_t handle, int32_t target, float roll)
{
	entity* e = need(handle, "PointEntity");
	need(target, "PointEntity");
	float me[16], mt[16];
	world_matrix(handle, me);
	world_matrix(target, mt);
	float d[3] = { mt[12] - me[12], mt[13] - me[13], mt[14] - me[14] };
	float len  = sqrtf(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
	if (len < 1e-9f) {
		return;
	}
	float pitch = deg(asinf(-d[1] / len)), yaw = deg(atan2f(-d[0], d[2]));
	(void)e;
	bb_rotate_entity(handle, pitch, yaw, roll, 1);
}

////////////////////////////////////////////////////////////////////////////////
// Names, copies, and appearance
////////////////////////////////////////////////////////////////////////////////
void bb_name_entity(int32_t handle, const char* name)
{
	entity* e = need(handle, "NameEntity");
	free(e->name);
	size_t length = name ? strlen(name) : 0;
	e->name       = static_cast<char*>(malloc(length + 1));
	memcpy(e->name, name ? name : "", length + 1);
}

const char* bb_entity_name(int32_t handle)
{
	entity*     e      = need(handle, "EntityName");
	const char* name   = e->name ? e->name : "";
	size_t      length = strlen(name);
	char*       copy   = static_cast<char*>(malloc(length + 1)); // The name can be changed while the program has this.
	memcpy(copy, name, length + 1);
	return copy;
}

// Looks for a child (or a child of a child, and so on) with the name.
int32_t bb_find_child(int32_t parent, const char* name)
{
	need(parent, "FindChild");
	for (uint32_t i = 0; i < entities.size; i++) {
		if (entities[i] && (entities[i]->parent == parent)) {
			if (entities[i]->name && name && same_name(entities[i]->name, name)) {
				return int32_t(i) + 1;
			}
			int32_t found = bb_find_child(int32_t(i) + 1, name);
			if (found) {
				return found;
			}
		}
	}
	return 0;
}

int32_t bb_copy_entity(int32_t handle, int32_t parent)
{
	need(handle, "CopyEntity");
	if (parent) {
		need(parent, "CopyEntity");
	}
	copy_was.clear();
	copy_now.clear();
	return copy_entity(handle, parent);
}

void bb_entity_order(int32_t handle, int32_t order)
{
	need(handle, "EntityOrder")->order = order;
}

void bb_entity_blend(int32_t handle, int32_t blend)
{
	need(handle, "EntityBlend")->blend = (blend < 1 || blend > 3) ? 1 : blend;
}

void bb_entity_shininess(int32_t handle, float shininess)
{
	need(handle, "EntityShininess")->shininess = shininess;
}

void bb_entity_auto_fade(int32_t handle, float near_distance, float far_distance)
{
	entity* e   = need(handle, "EntityAutoFade");
	e->fade_near = near_distance;
	e->fade_far  = far_distance;
}
}
